actions.script:
from = from || 'now-7d'; thru = thru || 'now'
queryNotices = []
// Requests by default: their SERVER spans, one a trace for a request this service received.
const filters = spanKind === 'all' ? [] : [{field:{name:'kind',op:'eq',value:'SERVER'}}]
// The structured fields add to the query; a name with * matches as a wildcard.
if (serviceName) filters.push({field:{name:'service.name',op:'eq',value:String(serviceName)}})
if (spanName) filters.push({field:{name:'name',op:String(spanName).includes('*') ? 'wildcard' : 'eq',value:String(spanName)}})
if (statusCode) filters.push({field:{name:'status_code',op:'eq',value:String(statusCode)}})
if (userId) filters.push({field:{name:'user.id',op:'eq',value:String(userId)}})
const millis = (value, label) => {
    if (value == null || String(value).trim() === '') return null
    const number = Number(String(value).trim())
    if (!Number.isFinite(number) || number < 0) { queryNotices.push(label+' is not a number of milliseconds and is ignored.'); return null }
    return Math.round(number * 1000000)
}
const minimum = millis(minDuration, 'Minimum duration'), maximum = millis(maxDuration, 'Maximum duration')
if (minimum != null || maximum != null) filters.push({field:Object.assign({name:'duration_nano',op:'range'},minimum != null ? {gte:minimum} : {},maximum != null ? {lte:maximum} : {})})
serviceOptions = []
try {
    const services = ec.service.sync().name('org.moqui.report.ReportServices.run#Query').parameters({query:{datasetId:'otel_spans',from,thru,
        aggregations:[{id:'service',type:'terms',role:'x-axis',params:{field:'service.name',size:200}}]}}).call()
    const frame = (services.frames || [])[0] || {fields:[]}, field = (frame.fields || []).find(field=>field.name==='service')
    serviceOptions = (field ? field.values : []).filter(value=>value != null).map(value=>({value:String(value),text:String(value)}))
} catch (error) { ec.logger.error('Trace service options failed: '+String(error)); queryNotices.push(String(error)) }
if (serviceName && !serviceOptions.some(item=>item.value===serviceName)) serviceOptions.unshift({value:serviceName,text:serviceName})
const result = ec.service.sync().name('org.moqui.report.ReportServices.query#Documents').parameters({
    datasetId: 'otel_spans', from, thru, queryString: queryString || '', filters,
    sort: [order === 'oldest' ? 'time' : '-time'], pageIndex: parseInt(pageIndex || '0', 10), pageSize: parseInt(pageSize || '50', 10)
}).call()
documentList = (result.hits || []).map(hit => Object.assign({documentId:hit.documentId || hit.id},hit.body || {}))
documentListCount = result.total || 0
documentListPageIndex = parseInt(pageIndex || '0', 10)
documentListPageSize = parseInt(pageSize || '50', 10)
documentListPageMaxIndex = Math.max(0,Math.ceil(documentListCount / documentListPageSize)-1)
documentListPageRangeLow = documentList.length ? documentListPageIndex*documentListPageSize+1 : 0
documentListPageRangeHigh = documentListPageIndex*documentListPageSize+documentList.length
queryNotices.push(...(result.notices || []).map(notice=>typeof notice==='string'?notice:notice.message || JSON.stringify(notice)))
